package com.trough.hot;
import android.os.*;import android.graphics.Rect;import java.io.File;import org.json.*;
/** Representative clear-to-contact sword gesture on the supported production fighter. */
final class HalfSwordTargetCheck implements Runnable {
 final HalfSwordView view;final HalfSwordAimCheck input;final Handler ui=new Handler(Looper.getMainLooper());final long began=SystemClock.uptimeMillis();int stage,steps,practiceBefore,practiceAfter;long clearStart,hitStart,transitionStart,pausedAt;JSONObject clearPose,hitPose;String clearLabel,hitLabel;float heldX,heldZ;double springPeak;boolean frozen,returned,resetCleared;long clearFrames,hitFrames,transitions,reactionFrames;int completedSteps;
 HalfSwordTargetCheck(HalfSwordView v){view=v;input=new HalfSwordAimCheck(v);}
 void need(boolean ok,String why)throws Exception{if(!ok)throw new Exception(why);}
 void start(){ui.postDelayed(this,150);}
 public void run(){try{
  need(SystemClock.uptimeMillis()-began<25000,"Target check timeout");need(view.isAttachedToWindow()&&view.renderVisible,"Scene unavailable");
  switch(stage){
   case 0:input.click("Training view");input.click("Reset physics");input.click("Stance support setup");stage=1;break;
   case 1:if(view.resetPending())break;need(view.requestCharacterStep(),"Initial step rejected");stage=2;break;
   case 2:if(view.characterBusy||view.characterSteps<1)break;need(view.characterAppliedStanceSupport,"Support missing");input.click("Run / pause");steps=view.characterSteps;stage=3;break;
   case 3:if(view.characterSteps-steps<60)break;input.observation();need(view.practiceHits==0,"Initial settling scored a hit");clearStart=view.targetClearFrames;transitionStart=view.targetTransitions;input.aim(30,30);steps=view.characterSteps;stage=4;break;
   case 4:if(view.characterSteps-steps<120)break;clearPose=input.observation();need(!view.bodyTargetTouching,"Torso obstacle overlaps clear pose");need(!view.targetTouching&&view.targetClearFrames>clearStart,"Aim did not clear training target");input.click("Run / pause");input.pausedSteps=-1;stage=5;break;
   case 5:if(!input.pausedScene(false))break;clearLabel=view.targetStatus.getText().toString();need(clearLabel.contains("Target · clear"),"Clear feedback missing");hitStart=view.targetContactFrames;practiceBefore=view.practiceHits;input.aim(0,0);input.click("Run / pause");steps=view.characterSteps;stage=6;break;
   case 6:if(view.practiceHits<=practiceBefore||Math.hypot(view.targetAppliedX,view.targetAppliedZ)<.02){need(view.characterSteps-steps<120,"No scored moving target within return window");break;}hitPose=input.observation();need(!view.bodyTargetTouching,"Torso obstacle overlaps hit pose");need(view.targetContactFrames>hitStart&&view.targetTransitions>transitionStart,"Neutral return did not hit target");input.click("Run / pause");input.pausedSteps=-1;stage=7;break;
   case 7:if(!input.pausedScene(true))break;hitLabel=view.targetStatus.getText().toString();practiceAfter=view.practiceHits;need(practiceAfter==practiceBefore+1&&hitLabel.contains("Hits "+practiceAfter),"Practice hit feedback missing");Rect visible=new Rect();need(view.targetStatus.isShown()&&view.targetStatus.getGlobalVisibleRect(visible)&&visible.width()>0&&visible.height()>0,"Visible hit feedback missing");heldX=view.targetAppliedX;heldZ=view.targetAppliedZ;springPeak=view.targetSpringPeak;need(view.targetSpringKicks==1&&Math.hypot(heldX,heldZ)>.015&&springPeak<=.12,"Spring response missing or unbounded");steps=view.characterSteps;pausedAt=SystemClock.uptimeMillis();stage=8;break;
   case 8:if(SystemClock.uptimeMillis()-pausedAt<500)break;need(view.characterSteps==steps&&view.targetAppliedX==heldX&&view.targetAppliedZ==heldZ,"Paused spring moved");need(Math.abs(view.targetConfig.getDouble(56)-(HalfSwordWeapon.TARGET_MIN[0]+heldX))<1e-7&&Math.abs(view.targetConfig.getDouble(72)-(HalfSwordWeapon.TARGET_MIN[2]+heldZ))<1e-7,"Spring query diverged from drawing");frozen=true;input.aim(30,30);input.click("Run / pause");steps=view.characterSteps;stage=9;break;
   case 9:if(view.characterSteps-steps<240)break;input.observation();input.click("Run / pause");input.pausedSteps=-1;stage=10;break;
   case 10:if(!input.pausedScene(false))break;need(Math.hypot(view.targetAppliedX,view.targetAppliedZ)<.001,"Spring did not return");returned=true;clearFrames=view.targetClearFrames-clearStart;hitFrames=view.targetContactFrames-hitStart;transitions=view.targetTransitions-transitionStart;reactionFrames=view.targetReactionFrames;completedSteps=view.characterSteps;input.click("Reset physics");stage=11;break;
   case 11:if(view.resetPending()||view.characterBusy)break;need(view.targetAppliedX==0&&view.targetAppliedZ==0&&view.targetSpringKicks==0&&view.targetSpringPeak==0,"Reset retained spring state");resetCleared=true;finish(null);return;
  }ui.postDelayed(this,stage==6?16:100);
 }catch(Throwable error){view.characterRunning=false;view.cancelAllTouchInputs();finish(error.toString());}}
 void finish(String error){try{JSONObject out=new JSONObject();out.put("spring_held_x",heldX).put("spring_held_z",heldZ).put("spring_peak_m",springPeak).put("paused_spring_frozen",frozen).put("spring_returned",returned).put("reset_spring_cleared",resetCleared);out.put("practice_hits_before",practiceBefore).put("practice_hits_after",practiceAfter);out.put("torso_touching",view.bodyTargetTouching).put("shapes",view.shapes).put("camera_yaw",view.yaw);out.put("passed",error==null).put("error",error==null?"":error).put("stage",stage).put("clear_observation",clearPose).put("hit_observation",hitPose).put("clear_label",clearLabel).put("hit_label",hitLabel).put("clear_frames",clearFrames).put("hit_frames",hitFrames).put("transitions",transitions).put("target_touching",view.targetTouching).put("reaction_frames",reactionFrames).put("physics_steps",completedSteps).put("module",HalfSwordBridge.loadedModuleSha256).put("time_ms",System.currentTimeMillis()).put("scope","Native aim gesture clear30/30 then neutral target contact; supported pose, visible feedback and paused matched GPU scene. Contact observation, not damage or independent sword dynamics.");Payloads.writeSmall(new File(view.getContext().getFilesDir(),"home/.trough/half-sword-target-check-result.json"),out.toString());}catch(Exception failed){android.util.Log.e("Trough","Target check result failed",failed);}}
}
